"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[7999],{98174(a,n,e){e.r(n),e.d(n,{assets:()=>u,contentTitle:()=>k,default:()=>d,frontMatter:()=>m,metadata:()=>i,toc:()=>r});const i=JSON.parse('{"id":"learning/courses/quantum-computing-in-practice/applications-of-qc","title":"Masalah apakah yang sesuai untuk komputer kuantum?","description":"Baca tentang cara kita memilih jenis masalah yang kami fikir mungkin mendapat manfaat daripada penyelesaian kuantum, dan lihat beberapa contoh terkini kerja daripada komuniti.","source":"@site/i18n/ms/docusaurus-plugin-content-docs/current/learning/courses/quantum-computing-in-practice/applications-of-qc.mdx","sourceDirName":"learning/courses/quantum-computing-in-practice","slug":"/learning/courses/quantum-computing-in-practice/applications-of-qc","permalink":"/learning/courses/quantum-computing-in-practice/applications-of-qc","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/quantum-computing-in-practice/applications-of-qc.mdx","tags":[],"version":"current","frontMatter":{"title":"Masalah apakah yang sesuai untuk komputer kuantum?","sidebar_label":"Masalah apakah yang sesuai untuk komputer kuantum?","description":"Baca tentang cara kita memilih jenis masalah yang kami fikir mungkin mendapat manfaat daripada penyelesaian kuantum, dan lihat beberapa contoh terkini kerja daripada komuniti.","notebook_path":"learning/courses/quantum-computing-in-practice/applications-of-qc.ipynb"},"sidebar":"tutorialsSidebar","previous":{"title":"QAOA berskala utiliti","permalink":"/learning/courses/quantum-computing-in-practice/utility-scale-qaoa"},"next":{"title":"Pemetaan","permalink":"/learning/courses/quantum-computing-in-practice/mapping"}}');var t=e(74848),s=e(28453);const m={title:"Masalah apakah yang sesuai untuk komputer kuantum?",sidebar_label:"Masalah apakah yang sesuai untuk komputer kuantum?",description:"Baca tentang cara kita memilih jenis masalah yang kami fikir mungkin mendapat manfaat daripada penyelesaian kuantum, dan lihat beberapa contoh terkini kerja daripada komuniti.",notebook_path:"learning/courses/quantum-computing-in-practice/applications-of-qc.ipynb"},k=void 0,u={},r=[{value:"Pengenalan",id:"introduction",level:2},{value:"Kesukaran klasik vs. kuantum",id:"kesukaran-klasik-vs-kuantum",level:2},{value:"Kelas kerumitan",id:"kelas-kerumitan",level:3},{value:"Komputer kuantum hari ini dan hadnya",id:"komputer-kuantum-hari-ini-dan-hadnya",level:3},{value:"Kawasan Aplikasi dan Kes Penggunaan",id:"kawasan-aplikasi-dan-kes-penggunaan",level:2},{value:"Kes Penggunaan 1: Mensimulasi dinamik hadron",id:"kes-penggunaan-1-mensimulasi-dinamik-hadron",level:3},{value:"Kes Penggunaan 2: Pengoptimuman kaca spin Ising",id:"kes-penggunaan-2-pengoptimuman-kaca-spin-ising",level:3},{value:"Kes Penggunaan 3: Ramalan struktur sekunder mRNA",id:"kes-penggunaan-3-ramalan-struktur-sekunder-mrna",level:3},{value:"Kesimpulan",id:"kesimpulan",level:2}];function l(a){const n={a:"a",annotation:"annotation",h2:"h2",h3:"h3",img:"img",li:"li",math:"math",mi:"mi",mn:"mn",mo:"mo",mrow:"mrow",ol:"ol",p:"p",semantics:"semantics",span:"span",ul:"ul",...(0,s.R)(),...a.components},{IBMVideo:i}=n;return i||function(a,n){throw new Error("Expected "+(n?"component":"object")+" `"+a+"` to be defined: you likely forgot to import, pass, or provide it.")}("IBMVideo",!0),(0,t.jsxs)(t.Fragment,{children:["\n","\n",(0,t.jsxs)(n.p,{children:["Tonton video tentang aplikasi pengkomputeran kuantum daripada Olivia Lanes, atau buka video dalam tetingkap berasingan di ",(0,t.jsx)(n.a,{href:"https://youtu.be/33QmsXhIlpU",children:"YouTube."})]}),"\n",(0,t.jsx)(i,{id:"134063426",title:"In this video, Olivia Lanes describes several possible applications of quantum computing at the utility scale. These include simulating hadrons and spin glasses, as well as modeling protein structure."}),"\n",(0,t.jsx)(n.h2,{id:"introduction",children:"Pengenalan"}),"\n",(0,t.jsx)(n.p,{children:"Dalam pelajaran sebelumnya, kita menangani satu masalah secara mendalam \u2014 menyelesaikan masalah pengoptimuman Max-Cut menggunakan formulasi QUBO. Hari ini kita akan mengambil pendekatan yang berbeza dan membincangkan aplikasi jangka pendek secara lebih luas. Kita akan mulakan dengan memberi anda gambaran tentang cara kita memilih jenis masalah yang kami fikir mungkin mendapat manfaat daripada penyelesaian kuantum. Kemudian, kita akan melihat beberapa contoh terkini kerja yang dilakukan dalam komuniti kita. Ini akan membantu anda mula membina intuisi untuk jenis masalah pengkomputeran kuantum yang berbeza dan cara kita mendekati penyelesaiannya."}),"\n",(0,t.jsx)(n.h2,{id:"kesukaran-klasik-vs-kuantum",children:"Kesukaran klasik vs. kuantum"}),"\n",(0,t.jsx)(n.p,{children:"Sebelum menyelami contoh-contohnya, mari kita terlebih dahulu bincangkan cara kita mengkaji dan mengkategorikan kesukaran pelbagai masalah. Sesetengah masalah boleh diselesaikan dengan mudah pada komputer klasik, dan kita tidak memerlukan komputer kuantum untuk menyelesaikannya. Sebaliknya, terdapat masalah yang sangat sukar yang memerlukan komputer kuantum untuk diselesaikan. Satu contoh terkenal adalah mencari faktor prima integer yang besar. Penyulitan RSA bergantung kepada kesukaran masalah ini, dan algoritma Shor direka untuk menyelesaikannya pada komputer kuantum. Contoh lain adalah mencari penyelesaian dalam set data yang tidak disusun \u2014 ini secara teorinya boleh diselesaikan oleh algoritma kuantum yang dikenali sebagai algoritma Grover. Walau bagaimanapun, kebanyakan pakar bersetuju bahawa jenis algoritma ini akan memerlukan pelaksanaan pembetulan ralat dan teknologinya masih belum sampai ke sana."}),"\n",(0,t.jsx)(n.p,{children:"Jadi, kita mencari masalah yang boleh kita tangani di suatu tempat dalam zon tengah antara yang sangat mudah dan sangat sukar \u2014 yang boleh ditangani oleh komputer kuantum hari ini, tetapi komputer klasik menghadapi masalah dengannya."}),"\n",(0,t.jsx)(n.h3,{id:"kelas-kerumitan",children:"Kelas kerumitan"}),"\n",(0,t.jsx)(n.p,{children:"Kesukaran masalah-masalah ini dikategorikan dan dianalisis dalam cabang sains komputer yang dipanggil teori kerumitan pengkomputeran. Terdapat banyak kelas kerumitan yang berbeza dalam pengkomputeran klasik, tetapi beberapa yang paling asas adalah:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"P: Masalah yang boleh diselesaikan dalam masa polinomial apabila skala masalah meningkat. Ia mudah diselesaikan."}),"\n",(0,t.jsx)(n.li,{children:"NP: Ini bermaksud polinomial tak tentu. Masalah-masalah ini tidak semestinya boleh diselesaikan dalam masa polinomial, tetapi jawapannya boleh disahkan dalam masa polinomial."}),"\n",(0,t.jsx)(n.li,{children:"NP-complete adalah masalah yang paling sukar dalam NP dan tidak mempunyai penyelesaian polinomial yang diketahui. Di sinilah masalah terkenal seperti jurujual pengembara dan permainan Sudoku berada."}),"\n",(0,t.jsx)(n.li,{children:"BPP, atau masalah polinomial ralat terbatas, yang boleh diselesaikan dalam ambang ralat tertentu oleh komputer klasik probabilistik dalam masa polinomial."}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"Apabila konsep pengkomputeran kuantum dicipta, orang meluangkan usaha yang besar untuk mencuba mengetahui kelas masalah yang boleh diselesaikan dengan cekap oleh jenis komputer baharu ini. Kelas masalah baharu telah dicipta:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"BQP, atau masalah polinomial kuantum ralat terbatas. Ini adalah setara kuantum dengan BPP: Ia adalah kelas masalah keputusan yang boleh diselesaikan oleh komputer kuantum dalam masa polinomial dengan peluang ralat yang kecil."}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{alt:"Hubungan yang disyaki antara kelas kerumitan",src:e(52600).A+"",width:"976",height:"682"})}),"\n",(0,t.jsx)(n.p,{children:"Semua kelas ini berada dalam kelas yang lebih besar yang kita panggil PSPACE. Di atas adalah gambar rajah hubungan yang disyaki antara beberapa kelas kerumitan, tetapi ini sangat sukar untuk dibuktikan secara matematikal. Anda akan perasan bahawa BQP tidak semestinya bertindih dengan NP-complete. Tetapi anda mungkin masih melihat beberapa pendekatan pengkomputeran kuantum yang bertujuan untuk mencuba menyelesaikan masalah dalam NP-complete."}),"\n",(0,t.jsx)(n.p,{children:"Salah satu salah faham yang biasa adalah bahawa tidak ada gunanya meneroka penyelesaian kuantum untuk sebarang masalah di mana bukti matematik untuk pecutan kuantum tidak ditemui. Tetapi bukti matematik bahawa algoritma kuantum lebih cepat daripada padanannya yang klasik adalah sukar ditemui. Shor dan Grover adalah dua daripada hanya segelintir contoh di mana ini telah dilakukan setakat ini. Malah, membuktikan secara ketat bahawa P dan NP adalah berbeza adalah salah satu soalan terbuka yang paling terkenal dalam semua matematik, walaupun semua intuisi memberitahu kita bahawa mereka mesti berbeza."}),"\n",(0,t.jsx)(n.p,{children:"Tetapi cara algoritma berskala dengan saiz masalah yang semakin meningkat \u2014 yang dicerminkan dalam kelas kerumitan \u2014 tidak selalu menjadi ciri yang paling relevan bagi sesuatu algoritma. Penskalaan ini sering merupakan senario kes terburuk. Ada kemungkinan bahawa, dalam praktik, senario kes terburuk bukan yang paling kerap kita hadapi."}),"\n",(0,t.jsx)(n.p,{children:"Hanya kerana bukti kesukaran adalah rumit tidak bermaksud kita tidak boleh membuat kemajuan. Kita memperkenalkan idea penyelesaian heuristik. Jika anda seorang ahli eksperimen, anda mungkin mengetahui dan menyukai jenis penyelesaian ini. Heuristik adalah sebarang pendekatan untuk menyelesaikan masalah yang pragmatik, tetapi tidak semestinya optimum, kerana penyelesaian tidak perlu optimum untuk berguna. Sebagai contoh, fikirkan tentang aplikasi kewangan. Kita masih belum menemui pecutan eksponen untuk kebanyakan algoritma kewangan yang boleh digunakan oleh kuantum, tetapi kita tidak memerlukan penyelesaian yang optimum. Dalam kewangan, walaupun penyelesaian yang hanya 0.1% lebih cekap boleh menyamai berbilion dolar keuntungan."}),"\n",(0,t.jsx)(n.h3,{id:"komputer-kuantum-hari-ini-dan-hadnya",children:"Komputer kuantum hari ini dan hadnya"}),"\n",(0,t.jsx)(n.p,{children:"Jadi, bagaimana kita mengetahui kes penggunaan dan masalah yang mungkin sesuai untuk pengkomputeran kuantum sekarang? Adakah terdapat alasan yang baik untuk mempercayai utiliti kuantum, atau malah kelebihan, boleh ditemui sama ada sekarang atau dalam masa terdekat?"}),"\n",(0,t.jsx)(n.p,{children:"Mungkin lebih mudah untuk terlebih dahulu menyebutkan perkara yang masalah itu pasti tidak harus ada. Ia tidak boleh memerlukan bilangan qubit yang besar. Kita belum mempunyai pemproses yang mempunyai ribuan hingga jutaan qubit. Itu adalah salah satu sebab utama mengapa algoritma Shor dan seumpamanya masih jauh dari direalisasikan. Litar juga tidak boleh terlalu dalam. Had kedalaman litar bergantung kepada banyak faktor, tetapi secara umum, jika eksperimen anda memerlukan kedalaman yang anda belum pernah lihat dicapai dalam sastera, ia mungkin tidak akan berjaya. Dan akhirnya, sebarang jenis algoritma yang kita tahu akan memerlukan pembetulan ralat tidak boleh dilakukan lagi."}),"\n",(0,t.jsxs)(n.p,{children:["Semua batasan ini ditangani dalam ",(0,t.jsx)(n.a,{href:"https://www.ibm.com/quantum/technology#roadmap",children:"peta jalan IBM Quantum\xae"})," dan kami menjangkakan untuk mencapai pembetulan ralat pada awal tahun 2030-an, tetapi buat masa ini, kita perlu mencari eksperimen yang menggunakan kebanyakan qubit yang kini tersedia pada QPU yang diberikan. Kita juga menekankan kepentingan mitigasi dan penindasan ralat. Dan akhirnya, harus ada sambungan yang jelas kepada aplikasi masa depan yang akan penting bagi masyarakat dan yang kita boleh lihat akhirnya membawa kepada kelebihan kuantum."]}),"\n",(0,t.jsx)(n.h2,{id:"kawasan-aplikasi-dan-kes-penggunaan",children:"Kawasan Aplikasi dan Kes Penggunaan"}),"\n",(0,t.jsx)(n.p,{children:"Sekarang mari kita bincangkan beberapa contoh kes penggunaan, yang tergolong dalam tiga kategori utama yang telah kita kenal pasti sebagai yang paling mungkin melihat hasil yang menggalakkan dalam jangka pendek hingga pertengahan:"}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:["Simulasi alam semula jadi. Kaedah klasik semasa bagi simulasi atom dan molekul adalah terhad oleh penerangan matematik yang tidak cekap tentang struktur atom. Menyimpan dan memanipulasi keadaan kuantum memerlukan sumber eksponen pada komputer klasik tetapi boleh dilakukan dengan cekap pada komputer kuantum. Ini boleh membawa kepada perkembangan dalam penangkapan karbon dioksida, bateri alternatif, atau penciptaan ubat baharu. Beberapa algoritma yang sangat relevan dalam kawasan ini adalah: Variational Quantum Eigensolver (VQE), yang digunakan untuk menganggarkan sifat tertentu sesuatu bahan, seperti keseimbangan atau keadaan tenaga minimum; algoritma Time Dynamics Simulation (TDS), yang digunakan untuk menganggarkan fungsi respons atau sifat spektral bahan; dan pendatang baharu, ",(0,t.jsx)(n.a,{href:"/learning/courses/quantum-diagonalization-algorithms/sqd-overview",children:"Sample-based Quantum Diagonalization (SQD)"}),", yang kami fikir akan semakin banyak didengar pada masa akan datang."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Pengoptimuman. Kawasan ini ada di mana-mana dalam pengkomputeran, jadi kes penggunaannya adalah banyak dan pelbagai. Beberapa contoh yang sering kita dengar adalah pengoptimuman portfolio dalam kewangan, reka bentuk industri, dan pengedaran serta rantaian bekalan. Algoritma yang paling biasa yang anda mungkin dengar berkaitan dengan kewangan adalah yang telah kita liputi secara mendalam: quantum approximate optimization algorithm, atau QAOA."}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Pembelajaran mesin kuantum. Kawasan ini telah menjana banyak keterujaan dalam beberapa tahun kebelakangan ini, tetapi kemungkinan besar QML tidak akan berguna secepat simulasi. Tetapi terdapat beberapa algoritma yang mengesankan yang sedang diusahakan untuk menangani beberapa kes penggunaan yang sangat penting. Beberapa kes penggunaan yang mungkin ini adalah pemprosesan bahasa semula jadi, analisis trafik rangkaian, dan malah pengesanan penipuan dalam transaksi kewangan. Algoritma yang relevan dalam kawasan ini adalah quantum support vector machine (QSVM), quantum neural networks (QNN), dan quantum generative adversarial networks."}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"Dalam kawasan aplikasi yang luas ini, komuniti melihat manfaat dalam kumpulan yang bekerja bersama yang memberi tumpuan kepada topik yang lebih khusus. IBM\xae mengetuai inisiatif yang dipanggil Kumpulan Kerja untuk cuba membantu kolaborator bertemu satu sama lain dan mencipta sinergi yang produktif dalam empat kawasan khusus: penjagaan kesihatan dan sains hayat, bahan dan pengkomputeran berprestasi tinggi (HPC), fizik tenaga tinggi, dan pengoptimuman. Dan baru-baru ini, kumpulan kerja kelima mengenai kemampanan telah diwujudkan."}),"\n",(0,t.jsx)(n.p,{children:"Kita sekarang akan menumpukan perhatian pada beberapa masalah yang baru-baru ini ditangani oleh beberapa kumpulan kerja ini. Matlamat utama di sini bukan untuk memahami setiap butiran eksperimen \u2014 ini boleh menakutkan walaupun untuk pakar jika makalah sedikit di luar bidang kepakaran anda. Matlamatnya hanyalah untuk membantu membangunkan intuisi untuk jenis masalah yang komputer kuantum sesuai untuknya dan cara kita mendekati penyelesaiannya. Dan jika anda berminat, kami menggalakkan anda membaca makalah penuh."}),"\n",(0,t.jsx)(n.h3,{id:"kes-penggunaan-1-mensimulasi-dinamik-hadron",children:"Kes Penggunaan 1: Mensimulasi dinamik hadron"}),"\n",(0,t.jsxs)(n.p,{children:["Pertama, kita akan menyelami makalah oleh kumpulan Martin Savage di Universiti Washington yang bertajuk ",(0,t.jsx)(n.a,{href:"https://journals.aps.org/prd/abstract/10.1103/PhysRevD.109.114510",children:"Quantum Simulations of Hadron Dynamics in the Schwinger Model Using 112 Qubits"}),"."]}),"\n",(0,t.jsx)(n.p,{children:'Jika anda bukan ahli fizik tenaga tinggi, anda mungkin masih biasa dengan istilah "hadron," seperti dalam Large Hadron Collider (LHC), yang merupakan pemecut zarah gergasi, 27-km dalam lilitan, yang memungkinkan pemerhatian boson Higgs akhirnya. Hadron adalah zarah komposit subatom yang terdiri daripada zarah kecil lain yang dipanggil quark. Beberapa contoh hadron adalah neutron dan proton.'}),"\n",(0,t.jsx)(n.p,{children:"Untuk sedikit konteks, LHC dibina untuk membolehkan kajian fizik asas dengan menghentam zarah pada tenaga yang sangat tinggi. Dengan LHC, saintis berharap untuk mengetahui lebih lanjut tentang alam semesta awal dan undang-undang asas alam semula jadi. Secara prinsipnya, interaksi zarah-zarah ini boleh disimulasi dari awal hingga akhir dengan komputer kuantum yang cukup berkuasa. Kita belum sampai ke sana, tetapi kita membuat kemajuan."}),"\n",(0,t.jsx)(n.p,{children:"Model Schwinger adalah model mudah yang popular digunakan untuk mensimulasi beberapa dinamik ini. Ia adalah model yang menggambarkan tingkah laku elektron dan positron yang berinteraksi melalui foton dalam 1+1D, bermaksud masa dan satu dimensi spatial. Model ini mempunyai banyak persamaan dengan chromodinamik kuantum (QCD), yang menggambarkan cara quark dan hadron berinteraksi, tetapi QCD sangat sukar disimulasi. Jadi, model Schwinger sering digunakan sebagai model mainan untuk menyiasat beberapa fenomena yang biasa kepada kedua-duanya."}),"\n",(0,t.jsx)(n.p,{children:"Untuk memahami mengapa mereka menangani masalah ini, mari kita tanya diri kita satu siri soalan."}),"\n",(0,t.jsx)(n.p,{children:"Pertama, mengapa mereka mempunyai alasan untuk mempercayai bahawa mensimulasi ini pada komputer kuantum akan berjaya sama sekali? Dalam kes ini, elektron dan positron dalam model Schwinger mempunyai kesan penapisan, menyebabkan korelasi antara fermion yang jauh merosot secara eksponen dengan pemisahan. Ini bermaksud tidak ada banyak interaksi jarak jauh yang diperlukan daripada qubit di satu sisi cip ke yang lain, yang kita tahu sangat terdedah kepada ralat. Jadi, ini adalah bagus untuk perkakasan yang ada pada hari ini."}),"\n",(0,t.jsx)(n.p,{children:"Seterusnya, mengapa topik ini menarik minat? Fizik tenaga tinggi secara amnya sangat menarik minat. Orang sanggup menghabiskan berbilion dolar untuk membina LHC, dan beribu-ribu saintis dan juruteknik dari seluruh dunia telah mendedikasikan kerjaya mereka kepada bidang ini. Walaupun model Schwinger adalah mudah dan tidak direka untuk merangkumi tiga dimensi spatial, ia masih merupakan penyederhanaan yang berguna bagi teori penuh."}),"\n",(0,t.jsx)(n.p,{children:"Terakhir, bagaimana kerja ini dilakukan, atau bagaimana kita akan mendekati masalah jika kita ingin meneruskan kerja ini? Dalam eksperimen jenis simulasi, VQE adalah salah satu pendekatan yang paling biasa, dan langkah pertama hampir selalu sama: sediakan keadaan dasar. Dalam kes ini, ia adalah keadaan vakum. Dalam eksperimen ini, mereka menggunakan versi VQE baharu yang dipanggil SC-ADAPT-VQE (yang bermaksud Scalable Circuits - Adaptive Derivative-Assembled Pseudo-Trotter ansatz-VQE) untuk menyediakan keadaan dasar dan paket gelombang hadron pada vakum ini. Langkah seterusnya adalah untuk membenarkan hadron berevolusi dalam masa. Akhirnya, kenal pasti boleh cerap yang anda ingin ukur dan ukurnya."}),"\n",(0,t.jsx)(n.p,{children:"Jika langkah-langkah itu terdengar agak biasa, tolak bahagian paket gelombang hadron, itu kerana langkah-langkah ini sangat mirip dengan apa yang kita liputi dalam contoh QAOA dalam pelajaran sebelumnya. Kita mulai dalam keadaan yang biasa (di sini keadaan vakum), dan kemudian kita biarkan ia berevolusi dalam masa dengan satu siri Hamiltonian yang dieksponenkan. Banyak algoritma variasi mengikuti pendekatan umum ini. Perbezaan besar di sini, bagaimanapun, adalah bahawa kita mencipta paket gelombang hadron yang berpusat dalam litar kita, sebelum kita mula membiarkannya berevolusi."}),"\n",(0,t.jsx)(n.p,{children:"Jadi, bagaimana kita mencipta paket gelombang? Pada vakum, hadron boleh dirangsang dengan mencipta pasangan fermion-antifermion pada tapak bersebelahan. Dengan menyediakan superposisi hadron seperti itu di lokasi yang berbeza, paket gelombang sewenang-wenang boleh disediakan. Para penulis memusatkan paket gelombang mereka di tengah-tengah litar untuk memerhati evolusi tanpa mencapai sempadan."}),"\n",(0,t.jsx)(n.p,{children:"Tetapi ingat: nama permainan ketika bekerja dengan QPU yang bising adalah memastikan kedalaman litar boleh diurus. Untuk melakukan ini, protokol SC-ADAPT-VQE menggunakan simetri dan hierarki dalam skala panjang untuk menentukan litar kuantum kedalaman rendah untuk penyediaan keadaan. Ini akan mencipta ansatz dengan bilangan parameter yang lebih kecil, dan oleh itu, kedalaman yang lebih cetek."}),"\n",(0,t.jsx)(n.p,{children:"Eksperimen ini dijalankan pada peranti IBM Quantum Heron dan merangkumi beberapa jenis mitigasi dan penindasan ralat yang berbeza: penyahgandingan dinamik, ekstrapolasi hingar sifar, pilinan Pauli, dan teknik yang baru-baru ini dibangunkan yang dipanggil operator decoherence renormalization."}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{alt:"Keputusan simulasi hadron",src:e(77894).A+"",width:"1158",height:"838"})}),"\n",(0,t.jsx)(n.p,{children:"Di atas adalah rajah daripada makalah yang menunjukkan boleh cerap yang diminati, kondensat chiral, yang pada asasnya adalah fasa bendalir lampau hadron. Kini, kita dapat melihat paket gelombang di pusat tapak yang telah ditetapkan untuk menjalankan eksperimen ini. Garisan hitam adalah keputusan bebas ralat daripada simulasi klasik (yang mahal dari segi pengkomputeran), manakala titik dengan bar ralat adalah keputusan daripada komputer kuantum IBM 133-qubit, Torino."}),"\n",(0,t.jsxs)(n.p,{children:["Kita melihat dua langkah masa yang berbeza dalam evolusi paket gelombang. Pada masa ",(0,t.jsxs)(n.span,{className:"katex",children:[(0,t.jsx)(n.span,{className:"katex-mathml",children:(0,t.jsx)(n.math,{xmlns:"http://www.w3.org/1998/Math/MathML",children:(0,t.jsxs)(n.semantics,{children:[(0,t.jsxs)(n.mrow,{children:[(0,t.jsx)(n.mi,{children:"t"}),(0,t.jsx)(n.mo,{children:"="}),(0,t.jsx)(n.mn,{children:"1"})]}),(0,t.jsx)(n.annotation,{encoding:"application/x-tex",children:"t=1"})]})})}),(0,t.jsxs)(n.span,{className:"katex-html","aria-hidden":"true",children:[(0,t.jsxs)(n.span,{className:"base",children:[(0,t.jsx)(n.span,{className:"strut",style:{height:"0.6151em"}}),(0,t.jsx)(n.span,{className:"mord mathnormal",children:"t"}),(0,t.jsx)(n.span,{className:"mspace",style:{marginRight:"0.2778em"}}),(0,t.jsx)(n.span,{className:"mrel",children:"="}),(0,t.jsx)(n.span,{className:"mspace",style:{marginRight:"0.2778em"}})]}),(0,t.jsxs)(n.span,{className:"base",children:[(0,t.jsx)(n.span,{className:"strut",style:{height:"0.6444em"}}),(0,t.jsx)(n.span,{className:"mord",children:"1"})]})]})]}),", anda dapat melihat bahawa kondensat chiral adalah sempit dan setempat, dan ia juga sepadan dengan simulasi klasik dengan baik. Pada ",(0,t.jsxs)(n.span,{className:"katex",children:[(0,t.jsx)(n.span,{className:"katex-mathml",children:(0,t.jsx)(n.math,{xmlns:"http://www.w3.org/1998/Math/MathML",children:(0,t.jsxs)(n.semantics,{children:[(0,t.jsxs)(n.mrow,{children:[(0,t.jsx)(n.mi,{children:"t"}),(0,t.jsx)(n.mo,{children:"="}),(0,t.jsx)(n.mn,{children:"14"})]}),(0,t.jsx)(n.annotation,{encoding:"application/x-tex",children:"t=14"})]})})}),(0,t.jsxs)(n.span,{className:"katex-html","aria-hidden":"true",children:[(0,t.jsxs)(n.span,{className:"base",children:[(0,t.jsx)(n.span,{className:"strut",style:{height:"0.6151em"}}),(0,t.jsx)(n.span,{className:"mord mathnormal",children:"t"}),(0,t.jsx)(n.span,{className:"mspace",style:{marginRight:"0.2778em"}}),(0,t.jsx)(n.span,{className:"mrel",children:"="}),(0,t.jsx)(n.span,{className:"mspace",style:{marginRight:"0.2778em"}})]}),(0,t.jsxs)(n.span,{className:"base",children:[(0,t.jsx)(n.span,{className:"strut",style:{height:"0.6444em"}}),(0,t.jsx)(n.span,{className:"mord",children:"14"})]})]})]}),", ia jauh lebih tersebar. Perbandingan dengan simulator tidak begitu sempurna sekarang, tetapi anda masih jelas dapat melihat persetujuan yang sangat baik antara teori dan data, yang menggalakkan."]}),"\n",(0,t.jsx)(n.p,{children:"Kesimpulannya, ini adalah contoh yang sangat menarik tentang jenis kerja simulasi yang mungkin pada awalnya anda tidak terfikir untuk mengaplikasikan pengkomputeran kuantum, tetapi yang menunjukkan potensi sebenar. Ia tidak sempurna tetapi anda tidak perlu menjadi pakar fizik zarah untuk melihat bahawa komputer kuantum secara tepat meramalkan perambatan keluar paket gelombang, yang tepat dengan apa yang kita jangkakan. Semoga kerja masa depan dalam bidang ini akan diteruskan dan ahli fizik tenaga tinggi akan terus mencari cara untuk memasukkan pengkomputeran kuantum dalam aliran kerja mereka. Matlamatnya adalah untuk menyelesaikan masalah teori yang sukar dengan lebih tepat dan menggunakan eksperimen untuk menerima atau menolak teori dengan harapan menemui fizik baharu, membina pengesan yang lebih baik, dan membawa kepada pemahaman yang lebih baik tentang alam semula jadi pada peringkat yang paling asas."}),"\n",(0,t.jsx)(n.h3,{id:"kes-penggunaan-2-pengoptimuman-kaca-spin-ising",children:"Kes Penggunaan 2: Pengoptimuman kaca spin Ising"}),"\n",(0,t.jsxs)(n.p,{children:["Contoh kita yang seterusnya memberi tumpuan kepada pengoptimuman dan akan menjadi kajian mendalam sebuah makalah yang bertajuk ",(0,t.jsx)(n.a,{href:"https://arxiv.org/abs/2405.13898",children:"Bias-Field Digitized Counterdiabatic Quantum Optimization"}),", yang dilakukan oleh ahli pasukan Kipu Quantum dan Universiti Basque Country di Sepanyol."]}),"\n",(0,t.jsx)(n.p,{children:'Dalam makalah tersebut, para penulis membangunkan kaedah pengoptimuman baharu dan menggunakannya untuk mencari keadaan dasar kaca spin Ising. Seperti yang kita bincangkan sebelumnya, banyak masalah pengoptimuman kombinatorial boleh diformulasikan semula sebagai menyelesaikan keadaan tenaga rendah Hamiltonian Ising. Model Ising menggambarkan interaksi susunan spin mikroskopik. Dalam beberapa rejim, model ini meramalkan bahawa spin berkelakuan seperti kaca, di mana momen magnet tidak teratur di atas apa yang dipanggil "suhu pembekuan."'}),"\n",(0,t.jsx)(n.p,{children:"Kita akan mulakan seperti yang kita lakukan sebelum ini dengan satu siri definisi. Yang pertama adalah counterdiabatic, yang merupakan jenis evolusi yang menindas kesan bukan adiabatik yang dialami oleh sistem, tanpa mengira seberapa cepat proses tersebut berlaku. Ingat teorem adiabatik dari episod lepas \u2014 anda biasanya perlu mengembangkan sistem dengan sangat perlahan jika anda mahu ia kekal dalam keadaan dasar. Ini adalah masalah besar kerana semakin perlahan kita mesti mengembangkan perkara, semakin lama kita mempunyai masa untuk ralat berlaku. Pemacu counterdiabatic (CD) bertujuan untuk memerangi ini dengan menambah terma yang menentang rangsangan yang tidak diingini ini. Idea utama di sini adalah untuk mempercepatkan keseluruhan eksperimen dan mengurangkan kedalaman litar kuantum dengan menindas rangsangan yang boleh menyebabkan peralihan spurious."}),"\n",(0,t.jsx)(n.p,{children:"Kini untuk kepingan jargon lain dalam tajuk: medan bias. Algoritma berulang lain, seperti VQE, mengambil parameter klasik ke dalam keadaan dan menggunakan pengoptimum klasik untuk mencari ruang parameter berdimensi banyak bagi set parameter yang menghasilkan nilai jangkaan minimum untuk Hamiltonian tetap. Dalam kes ini, sebaliknya mereka memvariasikan Hamiltonian setiap kali, bergerak secara adiabatik dari kes yang diketahui ke kes yang diminati. Untuk mengubah Hamiltonian, mereka hanya terus menggunakan nilai jangkaan Pauli-Z daripada satu ulangan sebagai medan bias dalam Hamiltonian untuk ulangan seterusnya. Dengan cara ini, mereka mengarahkan dinamik ke arah penyelesaian sebenar tanpa memerlukan pengoptimum klasik."}),"\n",(0,t.jsx)(n.p,{children:"Jadi, mengapa eksperimen ini menarik minat? Kaca spin Ising adalah menarik secara asasi dalam fizik, tetapi pendekatan baharu ini bahkan lebih umum daripada itu. Ia boleh digunakan untuk banyak masalah pengoptimuman, jadi makalah ini adalah menarik minat secara luas."}),"\n",(0,t.jsx)(n.p,{children:"Dan mengapa kita fikir ini akan berjaya? Algoritma yang mereka cadangkan mempercepatkan evolusi untuk mengurangkan kedalaman litar, sambil juga menindas peralihan bukan adiabatik. Selanjutnya, ia tidak bergantung pada sebarang subrutin pengoptimuman klasik, yang boleh menjadi isu yang membawa kepada dataran tandus dan terperangkap di minimum setempat. Akhirnya, para penulis juga memastikan untuk menyelaraskan interaksi dalam Hamiltonian masalah dengan sambungan perkakasan dalam QPU nyata, yang sentiasa sangat penting."}),"\n",(0,t.jsx)(n.p,{children:"Jadi, bagaimana kaedah ini berfungsi? Sekali lagi, ia tidak menggunakan sebarang pengoptimum klasik, tidak seperti kebanyakan algoritma kuantum berulang yang lain. Sebaliknya, dengan memasukkan penyelesaian dari setiap ulangan ke dalam input untuk yang seterusnya, algoritma pengoptimuman kuantum digitized bias-field secara beransur-ansur memperhalusi keadaan dasar, membawanya semakin dekat ke keadaan yang berevolusi akhir. Dan digabungkan dengan protokol counterdiabatic, kita boleh melakukan ini walaupun dengan litar kuantum kedalaman pendek yang sepatutnya berjalan lancar pada perkakasan yang bising."}),"\n",(0,t.jsx)(n.p,{children:"Jadi, apabila eksperimen dilakukan, para penulis memilih untuk menjalankan algoritma pada komputer kuantum IBM 127-qubit Brisbane. Di bawah adalah rajah yang menunjukkan ulangan ke-8 algoritma pengoptimuman untuk contoh kaca spin yang dijana secara rawak jiran terdekat pada 100 qubit. Mereka membandingkan keputusan simulasi klasik yang ideal daripada DCQO dan BF-DCQO, serta keputusan eksperimen yang dijalankan pada komputer kuantum. Mereka juga menunjukkan keputusan daripada penyelesai klasik yang dipanggil Gurobi sebagai rujukan. Dengan hanya 10 ulangan, BF-DCQO memberikan peningkatan drastik berbanding DCQO. Walaupun keputusan eksperimen sedikit berbeza daripada keputusan ideal akibat hingar, prestasi masih lebih baik daripada DCQO ideal. Ini menunjukkan bahawa masih ada kemajuan yang sangat baik sedang dibuat berkenaan pengoptimuman kuantum dan keputusan yang baik dilaporkan pada lebih daripada 100 qubit buat kali pertama."}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{alt:"Keputusan dari makalah kaca spin Ising",src:e(43410).A+"",width:"976",height:"682"})}),"\n",(0,t.jsx)(n.h3,{id:"kes-penggunaan-3-ramalan-struktur-sekunder-mrna",children:"Kes Penggunaan 3: Ramalan struktur sekunder mRNA"}),"\n",(0,t.jsxs)(n.p,{children:["Akhirnya, kita akan membincangkan makalah dari Moderna Pharmaceuticals yang bertajuk ",(0,t.jsx)(n.a,{href:"https://arxiv.org/abs/2405.20328",children:"mRNA Secondary Structure Prediction Using Utility-Scale Quantum Computers"}),"."]}),"\n",(0,t.jsx)(n.p,{children:"Pertama, ulasan singkat tentang mRNA. RNA pesuruh adalah sejenis RNA yang terlibat dalam sintesis protein. Ia pada dasarnya membaca arahan yang diberikan oleh DNA. Struktur sekunder mRNA adalah cara rantai itu dilipat, seperti yang ditunjukkan dalam gambar rajah di bawah. Dan masalah ramalan struktur sekunder RNA adalah masalah mencari lipatan yang paling stabil bagi urutan pangkalan atau nukleotida yang membentuk RNA: adenina (A), sitosina (C), urasil (U), dan guanina (G). Imej di bawah menunjukkan beberapa struktur lipatan biasa yang ditemui dalam mRNA, setiap warna mewakili jenis struktur sekunder yang berbeza. Apa yang menjadikan satu struktur lebih menguntungkan daripada yang lain tidak difahami dengan baik; yang boleh kita lakukan hanyalah mengira struktur mana yang menghasilkan tenaga bebas terendah berbanding keadaan tidak dilipat. Dan di situlah komputer kuantum berperanan."}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{alt:"Gambar rajah struktur sekunder mRNA",src:e(41923).A+"",width:"638",height:"842"})}),"\n",(0,t.jsx)(n.p,{children:"Jadi, mengapa struktur sekunder mRNA penting? Ramalan yang tepat tentangnya adalah penting bukan sahaja untuk memahami DNA dan gen kita, tetapi juga untuk mereka bentuk terapeutik berasaskan RNA, seperti vaksin COVID-19."}),"\n",(0,t.jsx)(n.p,{children:"Ini sudah lama diketahui sebagai masalah pengoptimuman yang berat untuk komputer klasik disebabkan bilangan konfigurasi yang mungkin yang sangat banyak. Untuk sesetengah konfigurasi, ia diketahui sebagai masalah NP-complete. Walau bagaimanapun, pada komputer kuantum, kita boleh memformulasikan ramalan struktur sekunder sebagai masalah pengoptimuman binari \u2014 sesuatu yang kita tahu cara menanganinya. Tambahan pula, sudah ada bukti dalam sastera tentang ramalan RNA yang tepat pada peranti kuantum berskala kecil dan simulator kuantum. Tetapi adakah ini akan berjaya pada perkakasan yang lebih besar?"}),"\n",(0,t.jsx)(n.p,{children:"Eksperimen ini dilakukan menggunakan sesuatu yang dipanggil conditional value at risk variational quantum eigensolver, yang merupakan pengubahsuaian algoritma VQE tradisional dan dijangka mencapai penumpuan yang lebih baik."}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{alt:"Keputusan dari makalah mRNA",src:e(65188).A+"",width:"1158",height:"686"})}),"\n",(0,t.jsx)(n.p,{children:"Plot di atas menunjukkan taburan kebarangkalian pengukuran bagi bitstring yang disampel, dengan tenaga yang sepadan untuk contoh 42-nukleotida, 80-qubit. Di sini, bitstring melambangkan pasangan nukleotida. Ia menggambarkan bahawa bitstring tenaga terendah yang ditemui oleh komputer kuantum sepadan dengan penyelesai klasik perbandingan, jadi itu adalah bagus. Juga ditunjukkan adalah struktur lipatan optimum bagi rantai nukleotida itu berdasarkan bitstring tenaga terendah yang ditemui oleh komputer kuantum."}),"\n",(0,t.jsx)(n.h2,{id:"kesimpulan",children:"Kesimpulan"}),"\n",(0,t.jsx)(n.p,{children:"Semoga tiga kes penggunaan ini telah memberi anda konteks yang mencukupi untuk memahami bagaimana kerja mutakhir dalam bidang ini kelihatan sekarang, dan keyakinan untuk mencuba eksperimen kuantum baharu yang mungkin tidak anda cuba sebelum ini."}),"\n",(0,t.jsx)(n.p,{children:"Ingat: pengkomputeran kuantum tidak sesuai untuk setiap masalah. Dan sebenarnya ini hanyalah bukti betapa baiknya kita dalam pengkomputeran klasik. Hanya kerana anda fikir anda boleh menggunakan pengkomputeran kuantum untuk masalah tidak bermaksud ia akan menghasilkan keputusan yang menarik; anda mesti mempertimbangkan penskalaan."}),"\n",(0,t.jsx)(n.p,{children:"Kedalaman litar adalah pedang bermata dua. Kita memerlukannya agak besar untuk melakukan kerja yang menarik yang komputer klasik tidak boleh, tetapi sekarang, kita tidak boleh meningkatkan kedalaman terlalu banyak kerana hingar perkakasan akan menyebabkan ketepercayaan berkurang. Ia semua tentang mencari zon tengah itu dan mengetahui bahawa ia adalah sasaran yang bergerak. Jadi, luangkan sedikit masa antara sekarang dan pelajaran seterusnya untuk memikirkan tentang masalah yang anda temui dalam penyelidikan anda, dan cara anda mungkin mendekatinya dengan apa yang telah kita pelajari setakat ini. Dan hei, penyelesaian anda mungkin tidak berjaya, dan itu tidak mengapa. Itulah sebabnya ini adalah penyelidikan."})]})}function d(a={}){const{wrapper:n}={...(0,s.R)(),...a.components};return n?(0,t.jsx)(n,{...a,children:(0,t.jsx)(l,{...a})}):l(a)}},52600(a,n,e){e.d(n,{A:()=>i});const i=e.p+"assets/images/complexity_classes-52979b588e98706373f7abc9b3f5f57c.avif"},77894(a,n,e){e.d(n,{A:()=>i});const i=e.p+"assets/images/hadron_paper-bc9c0a13fc3cd0e44b5c193902ce6dba.avif"},65188(a,n,e){e.d(n,{A:()=>i});const i=e.p+"assets/images/mrna_paper-4b1d694275f2539f69c49bfbb9b5ddd8.avif"},41923(a,n,e){e.d(n,{A:()=>i});const i=e.p+"assets/images/mrna_structure-962f2d5dfb98ac0a2e9c680e23d97ada.avif"},43410(a,n,e){e.d(n,{A:()=>i});const i=e.p+"assets/images/paper_results-aace6d8c4b97868e6cba7fc772e13ad9.avif"},28453(a,n,e){e.d(n,{R:()=>m,x:()=>k});var i=e(96540);const t={},s=i.createContext(t);function m(a){const n=i.useContext(s);return i.useMemo(function(){return"function"==typeof a?a(n):{...n,...a}},[n,a])}function k(a){let n;return n=a.disableParentContext?"function"==typeof a.components?a.components(t):a.components||t:m(a.components),i.createElement(s.Provider,{value:n},a.children)}}}]);